#pragma once

#include "IBMParticle.hpp"

/**
 * @brief Contact loads generated by the particle-container interaction.
 */
struct WallContactLoads {
    double forceX{};
    double forceY{};
    double maximumOverlap{};
    bool active{};
};

/**
 * @brief Apply a linear spring-dashpot contact model to a circular particle.
 *
 * The container occupies [0, width] x [0, height]. Contact forces are purely
 * normal in this benchmark commit; tangential wall friction is intentionally
 * postponed because it is not required before the first bottom impact.
 */
[[nodiscard]] WallContactLoads computeWallContact(
    const IBMParticle& particle,
    double width,
    double height,
    double normalStiffness,
    double normalDamping
);
